  }
  .story { scroll-snap-type: y proximity; }
  img { display: block; }
  .brand {
    position: absolute;
    top: 28px;
    left: 50%;
    transform: translateX(-50%);
    width: 210px;
    height: 56px;
    object-fit: contain;
  }
  .intro-title {
    position: absolute;
    top: 30%;
    left: 0;
    width: 100%;
    text-align: center;
    font-size: 20px;
    font-weight: bold;
  }
  .byline {
    position: absolute;
    top: calc(30% + 30px);
    left: 0;
    width: 100%;
    text-align: center;
    font-size: 14px;
    color: #c889d6;
  }
  .byline a { color: inherit; }
  .face-wrap {
    position: absolute;
    left: 50%;
    top: 43%;
    transform: translate(-50%, -50%);
    width: 300px;
    height: 165px;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .face-wrap img {
    width: 300px;
    height: 165px;
    object-fit: contain;
  }
  .face-wrap.warm { background: #ffdc72; }
  .cta {
    position: absolute;
    bottom: 24px;
