    transition: filter .15s ease, transform .15s ease;
  }
  .btn:hover { filter: brightness(1.12); }
  .btn:active { transform: scale(.98); }
  .bubble {
    position: absolute;
    left: 20px;
    top: 53%;
    max-width: 330px;
    min-width: 300px;
    padding: 13px 16px;
    background: #fff;
    color: #20151e;
    border: 0;
    border-radius: 9px;
    text-align: left;
    font: 14px/1.25 Georgia, serif;
    box-shadow: 0 2px 4px #090309;
  }
  .bubble:before {
    content: "";
    position: absolute;
    left: -9px;
    top: 16px;
    border-top: 9px solid transparent;
    border-bottom: 9px solid transparent;
    border-right: 11px solid #fff;
  }
  .bubble.center {
    left: 50%;
    top: calc(43% + 105px);
    transform: translateX(-50%);
    min-width: 300px;
  }
  .bubble.center:before {
    left: 20px;
    top: -9px;
    border: 0;
    border-left: 9px solid transparent;
    border-right: 9px solid transparent;
    border-bottom: 11px solid #fff;
  }
  .bubble mark {
    background: #ffe070;
    color: #171017;
    padding: 0 2px;
  }
  .grid-wrap {
    position: absolute;
    left: 50%;
    top: 48%;
    transform: translate(-50%, -50%);
    text-align: center;
  }
  .grid-wrap img {
    width: 820px;
    height: 1087px;
    object-fit: contain;
  }
  .grade-label {
    margin-top: 7px;
    font-size: 16px;
    font-weight: bold;
  }
  .grade-label small {
    display: block;
    margin-top: 2px;
    font-size: 12px;
    font-weight: normal;
  }
  .result {
    position: absolute;
    top: 7%;
    left: 0;
    width: 100%;
    text-align: center;
    line-height: 1.3;
    font-size: 17px;
  }
  .result strong { color: #ffdc70; font-size: 23px; }
  .bubble.rightish {
    left: auto;
    right: 20px;
  }
  @media (max-width: 900px) {
    .scene { min-height: 540px; }
    .grid-wrap { top: 47%; width: 100%; }
    .grid-wrap img { width: min(78vw, 580px); height: auto; }
    .bubble { left: 12px; min-width: 0; max-width: 250px; font-size: 12px; }
    .bubble.rightish { left: auto; right: 12px; }
    .face-wrap, .face-wrap img { width: 250px; height: 138px; }
    .cta { min-width: 0; width: 85%; }
  }
</style>
</head>
